  neighbor_type = NEIGH_2D;
  force_iteration_type = FORCE_ITER_NEIGH_FULL;
  binning_type = BINNING_KKSORT;
  comm_exchange_rate = 20;

  // set defaults

  thermo_rate = 0;
  dumpbinary_rate = 0;
  correctness_rate = 0;
  dumpbinaryflag = false;
  correctnessflag = false;
  timestepflag = false;
  lattice_offset_x = 0.0;
  lattice_offset_y = 0.0;
