// Class replicating LAMMPS Random velocity initialization with GEOM option
#define IA 16807
#define IM 2147483647
#define AM (1.0/IM)
#define IQ 127773
#define IR 2836

class LAMMPS_RandomVelocityGeom {
 private:
  int seed;
 public:

  KOKKOS_INLINE_FUNCTION
  LAMMPS_RandomVelocityGeom (): seed(0) {};

  KOKKOS_INLINE_FUNCTION
  double uniform() {
    int k = seed/IQ;
    seed = IA*(seed-k*IQ) - IR*k;
    if (seed < 0) seed += IM;
    double ans = AM*seed;
    return ans;
  }

  KOKKOS_INLINE_FUNCTION
  double gaussian() {
    double v1,v2,rsq;
    do {
      v1 = 2.0*uniform()-1.0;
      v2 = 2.0*uniform()-1.0;
      rsq = v1*v1 + v2*v2;
    } while ((rsq >= 1.0) || (rsq == 0.0));

    const double fac = sqrt(-2.0*log(rsq)/rsq);
    return v2*fac;
  }

  KOKKOS_INLINE_FUNCTION
  void reset(int ibase, double *coord)
  {
    int i;

    char *str = (char *) &ibase;
    int n = sizeof(int);

    unsigned int hash = 0;
    for (i = 0; i < n; i++) {
      hash += str[i];
      hash += (hash << 10);
      hash ^= (hash >> 6);
    }

    str = (char *) coord;
    n = 3 * sizeof(double);
    for (i = 0; i < n; i++) {
      hash += str[i];
      hash += (hash << 10);
      hash ^= (hash >> 6);
    }

    hash += (hash << 3);
    hash ^= (hash >> 11);
    hash += (hash << 15);

    // keep 31 bits of unsigned int as new seed
    // do not allow seed = 0, since will cause hang in gaussian()

    seed = hash & 0x7ffffff;
    if (!seed) seed = 1;

    // warm up the RNG

    for (i = 0; i < 5; i++) uniform();
  }
};


