    }
    if( (phase == 5) && (s.x(i,2)<s.sub_domain_lo_z)) {
      const int pack_idx = pack_count()++;
      if( pack_idx < pack_indicies.extent(0) ) {
        pack_indicies(pack_idx) = i;
        Particle p = s.get_particle(i);
        s.type(i) = -1;
        if(proc_pos[2] == 0)
          p.z += s.domain_z;
        pack_buffer(pack_idx) = p;
      }
    }
  } 

