	    for(int ma1 = MAX(0, (2 * ma - j - j2 + j1) / 2);
		ma1 <= MIN(j1, (2 * ma - j + j2 + j1) / 2); ma1++) {
	      double sumb1_r = 0.0;
	      double sumb1_i = 0.0;

	      const int ma2 = (2 * ma - j - (2 * ma1 - j1) + j2) / 2;

	      for(int mb1  = MAX( 0, (2 * mb - j - j2 + j1) / 2);
                mb1 <= MIN(j1, (2 * mb - j + j2 + j1) / 2); mb1++) {

