    const double uat2_r = uarraytot_r(j2,ma2,mb2);
    const double uat2_i = uarraytot_i(j2,ma2,mb2);
    sumb1_r += cga * (uat1_r * uat2_r - uat1_i * uat2_i);
    sumb1_i += cga * (uat1_r * uat2_i + uat1_i * uat2_r);
		/*sumb1_r += cgarray(j1,j2,j,mb1,mb2) *
